import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** `version` counts the person's saves; an edit sends the version it loaded, so a save made by
 *  someone else in the meantime refuses it. `statementCount` is how many statements have been
 *  taken for them; `statedTotal` the last one's due-total (two decimals, null when it was n/a or
 *  none was taken) and `statementDate` its date (yyyy-mm-dd, null when none was taken).
 *  `retired` is whether a retirement date is set (whatever the date), `retiredFrom` that date
 *  (yyyy-mm-dd, null when not retired). `held` is whether they have any hold; `holds` every hold, in the
 *  order added, from a date to a date (both inclusive; `to` null: open-ended). Their OPEN claims
 *  dated within a hold count in no live total, unless a statement binds them. `patrons` are the ids of the people they have named as patrons, in
 *  the order they were named. `grade` is the grade in force on the sheet's today when they were read;
 *  `grades` every grade recorded, by from-date (null: from the beginning of time, first). */
export type Person = {
  id: number;
  name: string;
  grade: string;
  grades: { grade: string; from: string | null }[];
  version: number;
  statementCount: number;
  statedTotal: string | null;
  statementDate: string | null;
  retired: boolean;
  retiredFrom: string | null;
  held: boolean;
  holds: { from: string; to: string | null }[];
  patrons: number[];
};

/** Whether `date` (yyyy-mm-dd) falls within any of the person's holds. */
export function heldOn(person: Person, date: string): boolean {
  return person.holds.some((h) => date >= h.from && (h.to === null || date <= h.to));
}

/** By person id, whether a date falls within one of that person's holds. */
export function heldOnBy(people: Person[]): (personId: number, date: string) => boolean {
  const byId = new Map(people.map((p) => [p.id, p]));
  return (personId, date) => {
    const p = byId.get(personId);
    return p !== undefined && heldOn(p, date);
  };
}

export const GRADES = ['A', 'B', 'C'] as const;

export const peopleKey = (sheet: string) => ['sheet', sheet, 'people'] as const;

/** The sheet's people in the order they were added, re-read whenever the sheet is loaded. */
export function usePeople(sheet: string) {
  return useQuery({
    queryKey: peopleKey(sheet),
    queryFn: () => getJson<Person[]>(`/api/sheets/${encodeURIComponent(sheet)}/people`),
    staleTime: 0,
    gcTime: 0,
  });
}

/** The person's grade in force on `date` (yyyy-mm-dd): the one from the latest date on or before
 *  it, the first one they were given applying from the beginning of time. */
export function gradeOn(person: Person, date: string): string {
  let found = person.grades[0]?.grade ?? person.grade;
  for (const g of person.grades) if (g.from === null || g.from <= date) found = g.grade;
  return found;
}
import { useEffect, useRef } from 'react';

// The actions of a person's row (statement, hold, retire) share the row's one error element; taking
// any of them clears the error another left showing, so only the latest action's error remains.
type Listener = { sheet: string; personId: number; owner: object; reset: () => void };
const listeners = new Set<Listener>();

/** Register a row action's `reset`; the returned `taken` is called as the action is taken. */
export function useRowAction(sheet: string, personId: number, reset: () => void): () => void {
  const owner = useRef({}).current;
  const resetRef = useRef(reset);
  resetRef.current = reset;
  useEffect(() => {
    const l: Listener = { sheet, personId, owner, reset: () => resetRef.current() };
    listeners.add(l);
    return () => {
      listeners.delete(l);
    };
  }, [sheet, personId, owner]);
  return () => {
    for (const l of listeners) {
      if (l.owner !== owner && l.sheet === sheet && l.personId === personId) l.reset();
    }
  };
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PersonCells, PersonColumns } from '../../slots/defs/personRow';
import { peopleKey, type Person } from '../people/usePeople';
import { useRowAction } from '../people/useRowAction';

/**
 * A person's retirement: whether they are retired and from when, and the date and button to retire
 * them (a blank date is the sheet's today). Set at all, they count as retired at once, whatever the
 * date: no claim dated after it is accepted, and the list hides them unless retired people are shown.
 */
function PersonRetire({ user, sheet, person }: { user: string; sheet: string; person: Person }) {
  const queryClient = useQueryClient();
  const [from, setFrom] = useState('');
  const retire = useMutation({
    mutationFn: (date: string) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/retire`, { from: date, user }),
    onSuccess: () => setFrom(''),
    onSettled: () => queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
  });
  const actionTaken = useRowAction(sheet, person.id, retire.reset);
  return (
    <>
      <td data-testid="person-retired">{person.retired ? 'yes' : 'no'}</td>
      <td data-testid="person-retired-from">{person.retiredFrom ?? ''}</td>
      <td>
        <input
          type="text"
          placeholder="yyyy-mm-dd"
          data-testid="person-retire-date"
          value={from}
          onChange={(e) => {
            setFrom(e.target.value);
            retire.reset();
          }}
        />{' '}
        <button
          type="button"
          data-testid="person-retire"
          disabled={retire.isPending}
          onClick={() => {
            actionTaken();
            retire.mutate(from);
          }}
        >
          Retire
        </button>
        {retire.isError && (
          <span data-testid="person-error" role="alert">
            {' '}
            Could not retire this person.
          </span>
        )}
      </td>
    </>
  );
}

export const contributions = [
  PersonColumns.fill({
    order: 30,
    Component: () => (
      <>
        <th>Retired</th>
        <th>Retired from</th>
        <th />
      </>
    ),
  }),
  PersonCells.fill({ order: 30, Component: PersonRetire }),
];
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PersonCells, PersonColumns } from '../../slots/defs/personRow';
import { peopleKey, type Person } from '../people/usePeople';
import { useRowAction } from '../people/useRowAction';

/**
 * A person's holds: whether they have any, a line per hold with its dates, and the dates and button
 * to add one (a blank from-date is the sheet's today, a blank to-date leaves it open-ended). Their
 * OPEN claims dated within a hold count in no live total, unless a statement binds them; their other
 * claims still count. A hold ends on its to-date: there is no release.
 */
function PersonHold({ user, sheet, person }: { user: string; sheet: string; person: Person }) {
  const queryClient = useQueryClient();
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const hold = useMutation({
    mutationFn: (dates: { from: string; to: string }) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/hold`, { ...dates, user }),
    onSuccess: () => {
      setFrom('');
      setTo('');
    },
    onSettled: () => queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
  });
  const actionTaken = useRowAction(sheet, person.id, hold.reset);
  return (
    <>
      <td data-testid="person-hold">{person.held ? 'yes' : 'no'}</td>
      <td>
        {person.holds.map((h, i) => (
          <div key={i} data-testid="person-hold-line">
            {h.from} – {h.to ?? 'open'}
          </div>
        ))}
      </td>
      <td>
        <input
          type="text"
          placeholder="from yyyy-mm-dd"
          data-testid="person-hold-from"
          value={from}
          onChange={(e) => {
            setFrom(e.target.value);
            hold.reset();
          }}
        />{' '}
        <input
          type="text"
          placeholder="to yyyy-mm-dd"
          data-testid="person-hold-to"
          value={to}
          onChange={(e) => {
            setTo(e.target.value);
            hold.reset();
          }}
        />{' '}
        <button
          type="button"
          data-testid="person-hold-toggle"
          disabled={hold.isPending}
          onClick={() => {
            actionTaken();
            hold.mutate({ from, to });
          }}
        >
          Hold
        </button>
        {hold.isError && (
          <span data-testid="person-error" role="alert">
            {' '}
            Could not add this hold.
          </span>
        )}
      </td>
    </>
  );
}

export const contributions = [
  PersonColumns.fill({
    order: 35,
    Component: () => (
      <>
        <th>Held</th>
        <th>Holds</th>
        <th />
      </>
    ),
  }),
  PersonCells.fill({ order: 35, Component: PersonHold }),
];
import { defineSlot } from '../Slot';
import type { Person } from '../../features/people/usePeople';

/** Extra column headers of the people list, one `<th>` per contribution. */
export const PersonColumns = defineSlot<{ user: string; sheet: string }>('person.columns');

/**
 * Extra cells of a person's row, one `<td>` per contribution, in the same order as their
 * PersonColumns headers. Everything kept per person (claims, ...) shows here, inside the row.
 */
export const PersonCells = defineSlot<{ user: string; sheet: string; person: Person }>('person.cells');
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
import { asString, useSearchParam } from '../../url/useSearchParam';

/**
